package com.vandorlabs.neoforge.canopy;

import com.google.gson.*;
import com.vandorlabs.persistence.LegacyBlockPosition;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.event.tick.LevelTickEvent;

/** Reconstruct released direct/helper/released-role observations in an actual loaded native world. */
final class CanopyTopologyHostChecks {
    private static final BlockPos ROOT=new BlockPos(8,200,8);private static long checks;private static int profiles;private static volatile Object sink;
    private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Canopy topology profile="+profiles+" "+why);}
    private static CompoundTag tag(int mount,BlockPos anchor,BlockPos pos){var tag=new CompoundTag();tag.putInt("CanopyMount",mount);tag.putLong("AnchorOffset",LegacyBlockPosition.pack(anchor.getX()-pos.getX(),anchor.getY()-pos.getY(),anchor.getZ()-pos.getZ()));return tag;}
    static void run(ServerLevel world)throws Exception{world.getChunkAt(ROOT);var installed=new ArrayList<NativeCanopyEntity>();
        try(var in=Files.newBufferedReader(Path.of(System.getenv("VANDOR_CANOPY_CONTACT_REFERENCE")))){for(String line;(line=in.readLine())!=null;){for(var old:installed)old.removing(true);for(var old:installed)world.setBlock(old.getBlockPos(),Blocks.AIR.defaultBlockState(),18);installed.clear();var row=JsonParser.parseString(line).getAsJsonArray();String kind=row.get(0).getAsString();int length=row.get(1).getAsInt(),mount=row.get(3).getAsInt(),bit=row.get(4).getAsInt(),role=row.get(9).getAsInt();var facing=Direction.from3DDataValue(row.get(2).getAsInt());var source=CanopyHostChecks.put(world,ROOT,kind,facing,tag(mount,ROOT,ROOT));installed.add(source);var direction=bit==1?facing.getCounterClockWise():bit==2?facing.getClockWise():bit==4?facing:facing.getOpposite();var query=ROOT.relative(direction,bit==8?length:1);var peer=row.get(5);
            if(!peer.isJsonNull()){var p=peer.getAsJsonArray();String other=p.get(0).getAsString();int peerLength=p.get(1).getAsInt(),peerMount=p.get(3).getAsInt();var peerFacing=Direction.from3DDataValue(p.get(2).getAsInt());var observed=ROOT.offset(p.get(4).getAsInt(),p.get(5).getAsInt(),p.get(6).getAsInt());var parent=p.get(7).getAsBoolean()?observed:query.relative(peerFacing,peerLength-1);need(!parent.equals(ROOT),"independent peer root");var ownerTag=tag(peerMount,parent,parent);if(role==2&&!parent.equals(query)){var offset=query.subtract(parent);ownerTag.putIntArray("CanopyFootprint",new int[]{0,0,0,offset.getX(),offset.getY(),offset.getZ()});ownerTag.putIntArray("CanopyReleasedHelpers",new int[]{1});}var owner=CanopyHostChecks.put(world,parent,other,peerFacing,ownerTag);installed.add(owner);if(role==1&&!parent.equals(query)){var helper=CanopyHostChecks.put(world,query,other,peerFacing,tag(peerMount,parent,query));installed.add(helper);}}
            var masks=NativeCanopyTopology.resolve(source);need(((masks.mask()&bit)!=0)==row.get(7).getAsBoolean(),"actual loaded direct/helper/released mask bit="+bit+" kind="+kind+" role="+role+" expected="+row.get(7)+" actual="+masks);need(((masks.roof()&bit)!=0)==row.get(8).getAsBoolean(),"actual loaded roof bit");if(profiles%5000==0){NativeCanopyLifecycle.prepare(source);need(source.publication().visual().mask()==masks.mask()&&source.publication().visual().roof()==masks.roof(),"immutable prepared contact publication");}profiles++;
        }}for(var old:installed)old.removing(true);for(var old:installed)world.setBlock(old.getBlockPos(),Blocks.AIR.defaultBlockState(),18);need(profiles==197376,"complete Source contact coverage");
        var pos=new BlockPos(64,230,64);world.getChunkAt(pos);var a=CanopyHostChecks.put(world,pos,"regular_canopy_glass",Direction.NORTH,tag(0,pos,pos));var b=CanopyHostChecks.put(world,pos.east(),"regular_canopy_glass",Direction.NORTH,tag(0,pos.east(),pos.east()));a.onLoad();b.onLoad();NativeCanopyLifecycle.prepare(a);need(a.publication().visual().mask()==2,"real fixed-glass neighbor connection");var before=a.getModelData();b.removing(true);world.removeBlock(b.getBlockPos(),false);NativeCanopyTopology.tick(new LevelTickEvent.Post(()->true,world));NativeCanopyLifecycle.prepare(a);need(a.publication().visual().mask()==0&&a.getModelData()!=before,"removal dirty section publishes replacement chunk model data");var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId();for(int i=0;i<100000;i++){NativeCanopyLifecycle.prepare(a);sink=a.getModelData();}long start=bean.getThreadAllocatedBytes(thread);for(int i=0;i<10000;i++){NativeCanopyLifecycle.prepare(a);sink=a.getModelData();}need(bean.getThreadAllocatedBytes(thread)-start==0,"settled ticks/model data allocate zero");need(NativeCanopyTargets.hasMembers(world),"loaded local membership present");a.onChunkUnloaded();need(!NativeCanopyTargets.hasMembers(world),"chunk unload retires last local target membership");a.onLoad();need(NativeCanopyTargets.hasMembers(world),"local reload restores membership");NativeCanopyLifecycle.prepare(a);a.removing(true);world.removeBlock(pos,false);
        System.out.println("[vandorlabs][canopy-host] contact topology PASS profiles="+profiles+" checks="+checks+" settledQueries=10000 allocated=0");
    }
}
